import { forwardRef } from 'react'

import { Polymorphic } from '../../utils/PolymorphicUtils'
import { Container } from '../shared/container/container'
import { Message } from './message/message'

export type ErrorPageData = {
  errorCode: number
  contactEmail: string
}

export type ErrorPageProps = {
  data: ErrorPageData
}

export const ErrorPage = forwardRef(function ErrorPage(
  { as: Component = 'main', data, className, ...props },
  ref,
) {
  return (
    <Component
      className={`relative z-10 flex-1 mt-20 ${className ?? ''}`}
      {...props}
      ref={ref}
    >
      <Container>
        <Message errorCode={data.errorCode} email={data.contactEmail} />
      </Container>
    </Component>
  )
}) as Polymorphic<'main', ErrorPageProps>
