import { ArrowRight } from 'lucide-react'
import { forwardRef } from 'react'
import { useTranslation } from 'react-i18next'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Button } from '../../shared/button/button'
import { Stack } from '../../shared/stack/Stack'

export type MessageActionsProps = {
  email: string
}

export const MessageActions = forwardRef(function MessageActions(
  { email, ...props },
  ref,
) {
  const { t } = useTranslation()

  return (
    <Stack
      align="center"
      justify="center"
      wrap="wrap"
      gap={3 * 4}
      {...props}
      ref={ref}
    >
      <Button
        as="a"
        size="lg"
        variant="primary"
        iconEnd={<ArrowRight className="h-4 w-4" />}
        href={`/`}
      >
        {t('errors.actions.go-back')}
      </Button>

      <Button as="a" size="lg" variant="outline" href={`mailto:${email}`}>
        {t('errors.actions.contact-me')}
      </Button>
    </Stack>
  )
}) as Polymorphic<'div', MessageActionsProps>
