import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Card } from '../../shared/card/card'
import { Stack } from '../../shared/stack/Stack'
import { MessageActions, MessageActionsProps } from './message-actions'
import { MessageDetails, MessageDetailsProps } from './message-details'
import { MessageIcon } from './message-icon'

type MessageProps = MessageDetailsProps & MessageActionsProps

export const Message = forwardRef(function Message(
  { errorCode, email, ...props },
  ref,
) {
  return (
    <Card size="lg" {...props} ref={ref}>
      <Stack gap={4 * 10} direction="column">
        <MessageIcon />
        <MessageDetails errorCode={errorCode} />
        <MessageActions email={email} />
      </Stack>
    </Card>
  )
}) as Polymorphic<'div', MessageProps>
