import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'

type CardProps = {
  size: 'sm' | 'md' | 'lg'
  interactive?: boolean
}

const sizeClasses: Record<CardProps['size'], string> = {
  sm: 'p-4 rounded-xl',
  md: 'p-6 rounded-2xl',
  lg: 'p-8 rounded-3xl',
}

export const Card = forwardRef(function Card(
  { as: Component = 'div', size, interactive, className, ...props },
  ref,
) {
  const classNames = [
    'border shadow-sm border-ink-200/60 bg-white/80 dark:border-ink-700/70 dark:bg-ink-800/80',
    sizeClasses[size],
    interactive
      ? 'transition-transform hover:-translate-y-1 hover:border-ink-300'
      : '',
    className,
  ]
    .filter(Boolean)
    .join(' ')

  return <Component className={classNames} {...props} ref={ref} />
}) as Polymorphic<'div', CardProps>
