import { forwardRef } from 'react'
import { useTranslation } from 'react-i18next'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Stack } from '../../shared/stack/Stack'
import { Typography } from '../../shared/typography/typography'

export type MessageDetailsProps = {
  errorCode: number
}

export const MessageDetails = forwardRef(function Details(
  { errorCode, ...props },
  ref,
) {
  const { t } = useTranslation()

  const overline = `${t('errors.code-prefix')} ${errorCode}`
  const headline = t(`errors.${errorCode}.headline`)
  const description = t(`errors.${errorCode}.description`)

  return (
    <Stack
      gap={4 * 4}
      direction="column"
      justify="center"
      align="center"
      {...props}
      ref={ref}
    >
      <Typography scale="overline" emphasis="default">
        {overline}
      </Typography>
      <Typography scale="h1" emphasis="strong">
        {headline}
      </Typography>
      <Typography scale="body" emphasis="default">
        {description}
      </Typography>
    </Stack>
  )
}) as Polymorphic<'div', MessageDetailsProps>
